 for line in subjects:gmatch('[^\r\n]+') do
  local title,key,kind,answers=line:match('^([^|]+)|([^|]+)|([^|]+)|(.+)$')
  addTopic(title,{title:lower()},answers)
  local entry=byTitle[title]
  entry.englishTitle=title
  entry.answerFamiliarity={}
  for index,word in ipairs(entry.words) do
   entry.answerFamiliarity[normalize(word)]=math.floor((index-1)/14)+1
  end
  byTitle['curated:'..kind..':'..key]=entry
 end
end)()
